 a descontar (> 2 m²)", "type": "openings_table", "types": ["Puerta", "Ventana", "Vitrina"]}, {"id": "substrate", "label": "Sustrato", "type": "single_select", "options": ["Concreto/block", "Sheetrock/yeso", "Metal", "Madera", "Mortero", "EIFS", "Otro"]}, {"id": "current_paint_type", "label": "Pintura actual estimada", "type": "single_select", "options": ["Látex", "Esmalte", "Elastomérica", "Acrílica", "Anticorrosiva", "No identificable"]}, {"id": "current_color", "label": "Color actual", "type": "text"}, {"id": "finish_type", "label": "Acabado", "type": "single_select", "options": ["Mate", "Satinado", "Semi-brillo", "Brillante"]}, {"id": "condition_rating", "label": "Estado (1=excelente, 5=muy mala)", "type": "rating_1_5"}, {"id": "damages", "label": "Daños observados", "type": "multi_select", "options": ["Descascarado", "Manchas humedad", "Hongos/moho", "Fisuras", "Grafiti", "Decoloración", "Eflorescencia", "Óxido", "Ninguno"]}, {"id": "prep_required", "label": "Preparación requerida", "type": "multi_select", "options": ["Lavado a presión", "Lijado", "Resane", "Sellador", "Imprimante anticorrosivo", "Antihongos"]}, {"id": "coats_recommended", "label": "Manos de pintura", "type": "single_select", "options": ["1", "2", "3"]}, {"id": "recommended_system", "label": "Sistema sugerido (marca/producto)", "type": "text"}, {"id": "photos", "label": "Fotos del elemento", "type": "photos", "min": 3, "required_labels": ["Panorámica", "Detalle daño", "Detalle textura"]}, {"id": "notes", "label": "Observaciones", "type": "textarea"}]}, {"id": "interior", "title": "Interior", "order": 3, "type": "repeating_block", "block_label": "Ambiente interior", "fields": [{"id": "room_type", "label": "Tipo de ambiente", "type": "single_select", "options": ["Lobby/área pública", "Área de cajas", "Oficina privada", "Sala de espera", "Back office", "Pasillo", "Baño público", "Baño empleados", "Bóveda", "Cuarto técnico/IT", "Cocina/pantry", "Almacén", "Otro"]}, {"id": "room_name", "label": "Nombre del ambiente", "type": "text"}, {"id": "length_m", "label": "Largo (m)", "type": "number"}, {"id": "width_m", "label": "Ancho (m)", "type": "number"}, {"id": "height_m", "label": "Alto/puntal (m)", "type": "number"}, {"id": "walls_gross_m2", "label": "Área paredes bruta", "type": "computed", "formula": "2 * (length_m + width_m) * height_m"}, {"id": "ceiling_m2", "label": "Área cielo raso", "type": "computed", "formula": "length_m * width_m"}, {"id": "openings", "label": "Aperturas a descontar", "type": "openings_table", "types": ["Puerta", "Ventana"]}, {"id": "walls_substrate", "label": "Sustrato paredes", "type": "single_select", "options": ["Block", "Sheetrock", "Concreto", "Otro"]}, {"id": "walls_paint_type", "label": "Pintura actual paredes", "type": "single_select", "options": ["Látex mate", "Látex satinado", "Esmalte", "Epóxica", "No identificable"]}, {"id": "walls_color", "label": "Color paredes", "type": "text"}, {"id": "walls_condition", "label": "Condición paredes (1-5)", "type": "rating_1_5"}, {"id": "walls_to_paint", "label": "¿Pintar paredes?", "type": "boolean", "default": true}, {"id": "ceiling_type", "label": "Tipo de cielo raso", "type": "single_select", "options": ["Pladur/sheetrock", "Plafón mineral", "Concreto", "Metálico", "No aplica"]}, {"id": "ceiling_to_paint", "label": "¿Pintar cielo raso?", "type": "boolean"}, {"id": "damages", "label": "Daños observados", "type": "multi_select", "options": ["Humedad", "Manchas", "Fisuras", "Descascarado", "Hongos", "Ninguno"]}, {"id": "photos", "label": "Fotos del ambiente", "type": "photos", "min": 2}, {"id": "notes", "label": "Observaciones", "type": "textarea"}]}, {"id": "parking", "title": "Parqueo y áreas de piso exterior", "order": 4, "fields": [{"id": "has_parking", "label": "¿Tiene parqueo propio?", "type": "boolean"}, {"id": "parking_spaces", "label": "Cantidad de espacios", "type": "number"}, {"id": "surface_type", "label": "Tipo de superficie", "type": "single_select", "options": ["Asfalto",