"recommended_system_justification", "label": "Justificación técnica de la recomendación", "type": "textarea"}, {"id": "preparation_required", "label": "Trabajos previos requeridos", "type": "multi_select", "options": ["Hidrolavado a presión", "Remoción de sistema existente", "Tratamiento puntual de oxidación", "Reparación de fisuras", "Reconstrucción de pendientes", "Sustitución de sumideros", "Reparación de parapetos", "Limpieza profunda"]}, {"id": "photos", "label": "Fotos de la cubierta", "type": "photos", "min": 5, "required_labels": ["Panorámica de la cubierta", "Detalle de patología principal", "Perímetro / parapeto", "Sumidero", "Penetración representativa"]}, {"id": "notes", "label": "Observaciones adicionales", "type": "textarea"}]}, {"id": "interior_inspection", "title": "Inspección interior (techo desde abajo)", "order": 3, "type": "repeating_block", "block_label": "Ambiente interior afectado", "optional": true, "fields": [{"id": "room_name", "label": "Ubicación", "type": "text"}, {"id": "ceiling_type", "label": "Tipo de cielo raso", "type": "single_select", "options": ["Plafón mineral", "Pladur/sheetrock", "Concreto expuesto", "Madera", "Sin cielo raso", "Otro"]}, {"id": "moisture_signs", "label": "Signos de humedad observados", "type": "multi_select", "options": ["Manchas activas", "Manchas secas (históricas)", "Eflorescencia", "Desprendimiento de plafón", "Goteo activo", "Hongos", "Ninguno"]}, {"id": "photos", "label": "Fotos interiores", "type": "photos", "min": 1}]}]}'::jsonb,
