le", "columns": ["Largo (m)", "Ancho (m)"], "auto_calc_area": true, "min_rows": 1}, {"id": "height_m", "label": "Altura libre interior (m)", "type": "number"}, {"id": "thermal_bridges", "label": "Puentes térmicos identificados", "type": "multi_select", "options": ["Estructura metálica vista", "Sin selladura en juntas", "Penetraciones sin aislar", "Puerta no aislada", "Ninguno aparente"]}, {"id": "moisture_issues", "label": "Problemas de humedad / condensación", "type": "multi_select", "options": ["Condensación interior visible", "Goteo por condensación", "Hongos por humedad", "Filtraciones desde exterior", "Ninguno"]}, {"id": "recommended_system", "label": "Sistema recomendado", "type": "single_select", "options": ["Espuma PUF proyectada in-situ (2-4 pulgadas)", "Espuma PUF densidad alta + recubrimiento", "Paneles aislantes prefabricados", "Pintura térmica reflectiva", "Sistema híbrido"]}, {"id": "thickness_recommended_mm", "label": "Espesor recomendado (mm)", "type": "number"}, {"id": "photos", "label": "Fotos", "type": "photos", "min": 3}, {"id": "notes", "label": "Observaciones", "type": "textarea"}]}]}'::jsonb,
